def tr(key, lang='en', **kwargs):
    return COPY[key][LANGS.index(lang) if lang in LANGS else 0].format(**kwargs)


def install(locales):
    for index, lang in enumerate(LANGS):
        locales[lang]['btn_workout'] = COPY['title'][index]
        locales[lang]['btn_workout_goals'] = COPY['goals'][index]

